function injectWorkloadId(simulation, defaultWorkloadId) {
  const workloadId = typeof simulation.workloadId === "string" ? simulation.workloadId : defaultWorkloadId;
  const childSimulations = Array.isArray(simulation.childSimulations) ? simulation.childSimulations.map((child) => injectWorkloadId(child, workloadId)) : undefined;
  return {
    ...simulation,
    workloadId,
    ...childSimulations ? { childSimulations } : {}
  };
}

